#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Сборка REPORT-OCSHIFT-01.md: текст — мой, числа — из gha_out/ocshift_test/analysis.json (GitHub Actions),
run/facts_ocshift.json, gha_out/ocshift_chain/power.json тем же форматированием, каким их сверяет ledger.py audit.
  python3 report_ocshift.py [ANALYSIS.json FACTS.json OUT.md]
Каркас написан до данных теста; формулировки итога и раздела «для главного вопроса» дописываются после данных (DEVIATIONS.md)."""
import json
import os
import sys

X = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(os.path.dirname(X))
a = sys.argv[1:]
J = lambda p: json.load(open(p if os.path.isabs(p) else os.path.join(ROOT, p), encoding='utf-8'))  # noqa: E731
r = J(a[0] if a else 'gha_out/ocshift_test/analysis.json')
fa = J(a[1] if len(a) > 1 else 'gha_out/ocshift_facts/facts_ocshift.json')
pw = J('gha_out/ocshift_chain/power.json')
OUT = a[2] if len(a) > 2 else os.path.join(X, 'REPORT-OCSHIFT-01.md')
EV = ('AGREE', 'NB-AGREE', 'LR-AGREE', 'NB-IND', 'FAM-AGREE', 'CONF', 'VETO', 'MIX-LR')
V = r['method']['valid']
E = r['envs']


def n(x, d=3, sign=False):
    s = f'{abs(x):.{d}f}'.replace('.', ',')
    if x < 0 and float(s.replace(',', '.')) != 0:
        return '−' + s
    return ('+' if sign and x > 0 else '') + s


def ci(e, d=4, key='ci'):
    return f"[{n(e[key][0], d, True)}; {n(e[key][1], d, True)}]"


def zero(e):
    """Пометка описательной записи: все ли три интервала по одну сторону нуля."""
    los, his = [e[k][0] for k in ('ci', 'ci_percentile', 'ci_basic')], [e[k][1] for k in ('ci', 'ci_percentile', 'ci_basic')]
    return '' if (max(his) < 0 or min(los) > 0) else '°'


def cz(e, d=4):
    return ci(e, d) + zero(e)


def reading(k):
    """PREREG §5: «не решено» при мощности < 0,05 читается как «не проверено»."""
    v = r['verdicts'][k]
    return v.replace('не решено', 'не проверено', 1) if v.startswith('не решено') and pw[k]['reading_power'] < 0.05 else v


def short(h):
    return h.replace('pythia-', '')


R1, R2, R3, R4 = r['R1'], r['R2'], r['R3'], r['R4']
D = lambda k: r[f'descr_{k}']  # noqa: E731
M, per, cnt = fa['mean'], fa['per_env'], fa['counts']
nv = fa['n_valid']
L = []
w = L.append
w('# OCSHIFT-01 «ОЦЕНЩИК-СДВИГИ» — отчёт (15.11.2026)')
w('')
w('Главный вопрос Neu — оценщик, который не обманывается под давлением отбора. OCSHIFT-01 спрашивал на десяти свежих средах (диапазоны a ∈ [X00, X99], X = 4…8, по две подсказки; те же девять голов Pythia): лучше ли одна лучшая голова, чем лучший из восьми оценщиков толпы; даёт ли сам отбор между головами самообман без сдвига; что лучше — CONF или LR-AGREE.')
w('- **Предрегистрация — коммит 2721a7fa** (`PREREG-OCSHIFT-01.md`; совет 60 — три линзы).')
w('- **Совет 61** оценил отчёт: принято единогласно; вердикты кода остались, формулировки сужены по его решению (`docs/council/2026-11-15_OCSHIFT-01-report_session61.md`).')
w(f"- **Прогон** — Kaggle, Tesla T4 × 2, извлечение {n(fa.get('extraction_seconds', 0), 1)} с (`run/out/kaggle_log.json`); {fa['n_problems']['all']} задач: {fa['n_problems']['id']} ID и {fa['n_problems']['ood']} OOD в {fa['n_envs']} средах.")
w(f"  - Сырой вывод закоммичен до анализа (коммит 45500072287f). Анализ — GitHub Actions, {n(fa['analysis_seconds'], 0)} с, {r['B']} повторов; хеши сверены в том же задании.")
w('- **Числа** — из `gha_out/ocshift_test/analysis.json`; производные — из `gha_out/ocshift_facts/facts_ocshift.json` (`facts_ocshift.py`, тоже GitHub Actions). Отчёт собирает `report_ocshift.py`.')
w('  - `ledger.py audit` по `analysis.json`, `facts_ocshift.json`, `power.json`, `analysis_pilot.json` и журналу Kaggle — «не найдено» 0. Большинство чисел аудит считает неинформативными (они встречаются в данных слишком часто), поэтому ключевые числа сверены отдельно по ключам json: `check_report_ocshift.py`, все совпали.')
w('')
w('## Итог')
w(f"**Вердикт кода — «{r['verdict']}».** " + ('Проверки метода пройдены' if r['method']['ok'] else 'ПРОВЕРКИ МЕТОДА НЕ ПРОЙДЕНЫ')
  + f": годных сред {nv} из {fa['n_envs']}, сверка цепочки — " + ('прошла' if r['check_ok'] else 'НЕ ПРОШЛА') + '.')
di, dd, sd = D('D1: разность незнания'), D('D1: разность самообмана'), fa['selection_deception']
lo1 = R1['leave_one_range_out']
flip = [g for g, v in lo1['mean_without'].items() if v * R1['delta'] <= 0]
w('')
w('**Коротко.**')
bi, st_, rg = fa['bias'], fa['sign_test'], fa['regime']
out_all = all(not v for v in bi['R2']['point_inside'].values())
w(f"- **Отбор головы по наибольшей заявке (CONF) завышает заявку уже на ID, без сдвига, — подтверждено (R2), на этих десяти средах.** Точка — {n(R2['delta'], 3, True)}; величина не установлена. Повторы бутстрепа смещены (z₀ {n(R2['z0'], 3, True)}), и точка лежит " + ('вне всех трёх интервалов' if out_all else 'не во всех интервалах') + f", так что три интервала — не три опоры. Опора вывода — нормальная граница ({n(R2['normal_bound']['upper'], 4, True)}, ниже нуля) и знак в {st_['R2']['n_same_sign']} средах из {st_['R2']['n']}. Объяснение не проверялось.")
w(f"- **Одна лучшая голова против толпы — не решено (R1).** Точка {n(R1['delta'], 3, True)} меньше наименьшего обнаружимого эффекта ({n(pw['R1']['mde_power08'])}): опыт такой эффект не различает. Вывод даёт один интервал из трёх, а знак держится на одном диапазоне: без X = {', '.join(flip)} среднее меняет знак.")
w(f"  - «Лучший из восьми» выбран задним числом по правде теста, поэтому сравнение смещено в пользу толпы. Описательно: лучший задним числом оценщик толпы точнее на {n(di['delta'])}, одна голова честнее на {n(-dd['delta'])}.")
w(f"- **CONF лучше LR-AGREE — подтверждено (R3), но только в среднем по этим десяти средам.** Знак тот же в {st_['R3']['n_same_sign']} средах из {st_['R3']['n']}; между средами разность различается (R4); на трёх прежних сдвигах знак был обратным ({n(pw['R3']['effect'], 4, True)}). Общего вывода об этой паре оценщиков нет.")
w(f"- **Строгая ветвь** (п. 4 решения совета 60 дословно): R2 — «{R2['verdict_strict']}», R3 — «{R3['verdict_strict']}». У обоих граница BC за разрешением повторов.")
w('- **Метод интервалов нужно чинить до следующего теста** (совет 61): бутстреп с возвращением смещает повторы в сторону вывода.')
w('')
w('**По правилам.**')
w(f"- **R1 (одна голова против толпы) — «{reading('R1')}».** Среднее по средам [ИОИ(ONE-BEST) − ИОИ лучшего из восьми]: {n(R1['delta'], 4, True)}, ДИ BC 99,5 % {ci(R1)}, процентильный {ci(R1, key='ci_percentile')}, обратный {ci(R1, key='ci_basic')}.")
w(f"  - Средний ИОИ: ONE-BEST {n(M['ONE-BEST']['ioi'])}, лучший из восьми задним числом {n(M['MIN8']['ioi'])}. По точкам ONE-BEST лучше в {cnt['one_beats_min8']} средах из {nv}.")
w(f"- **R2 (самообман от отбора без сдвига) — «{reading('R2')}».** Среднее по средам [T − C у CONF на ID, кросс-подгонка]: {n(R2['delta'], 4, True)}, ДИ BC {ci(R2)}, процентильный {ci(R2, key='ci_percentile')}, обратный {ci(R2, key='ci_basic')}.")
w(f"  - Нормальное приближение той же точки, без бутстрепа: {n(R2['normal_descr']['mean'], 4, True)} при стандартной ошибке {n(R2['normal_descr']['se'], 4)} (описательно).")
w(f"- **R3 (CONF против LR-AGREE, слово автора) — «{reading('R3')}».** Среднее по средам [ИОИ(CONF) − ИОИ(LR-AGREE)]: {n(R3['delta'], 4, True)}, ДИ BC {ci(R3)}, процентильный {ci(R3, key='ci_percentile')}, обратный {ci(R3, key='ci_basic')}. По точкам CONF лучше в {cnt['conf_beats_lr']} средах из {nv}.")
w(f"- **R4 (различие R3 между средами) — «{reading('R4')}».** Q = {n(R4['Q'], 2)} при {R4['df']} степенях свободы; p по бутстрепу с центрированием — не больше 1/{r['B']} (предел разрешения повторов); p по χ² тоже ниже 0,0025, но опирается на те же стандартные отклонения смещённого бутстрепа.")
w('')
w('| среда | ONE-BEST: голова | T / C / ИОИ | лучший из восьми: кто, ИОИ | LR-AGREE | CONF | оракул | голов в толпе |')
w('|---|---|---|---|---|---|---|---|')
for q in V:
    v, p = per[q], E[q]['point']
    w(f"| X = {E[q]['meta'].get('X', q)}, p = {E[q]['meta'].get('p', '')} | {short(v['one_best'])} | {n(v['T_one'])} / {n(v['C_one'])} / {n(v['ioi_one'])} | {v['best8']}, {n(v['ioi_best8'])} | "
      f"{n(p['ioi LR-AGREE'])} | {n(p['ioi CONF'])} | {n(v['oracle'])} | {fa['crowd_size'][q]} |")
w(f"| **среднее** | | {n(M['ONE-BEST']['T'])} / {n(M['ONE-BEST']['C'])} / {n(M['ONE-BEST']['ioi'])} | {n(M['MIN8']['ioi'])} | {n(M['LR-AGREE']['ioi'])} | {n(M['CONF']['ioi'])} | {n(fa['mean_oracle'])} | |")
w('')
w('## 1. Прогон')
w(f"- **Среды:** {fa['n_envs']}, годных {nv}. Голов в толпе — от {fa['crowd_size_range']['min']} до {fa['crowd_size_range']['max']} (проверка метода — только по ID).")
ex = {q: v for q, v in fa['excluded_heads'].items() if v}
w('- **Не прошли проверку метода:** ' + ('; '.join(f"{q} — {', '.join(short(h) for h in v)}" for q, v in ex.items()) if ex else 'таких голов нет') + '.')
w('- **ONE-BEST по средам:** ' + ', '.join(f"{short(h)} — {c}" for h, c in sorted(fa['one_best_heads'].items(), key=lambda t: -t[1])) + f". Лучшая на ID оказалась лучшей и вне диапазона в {cnt['one_best_is_best_ood']} средах из {nv}.")
w(f"- **Режим:** точность лучшей вне диапазона головы в среднем {n(fa['mean_best_ood_acc'])}; оракул (верна хоть одна голова) — {n(fa['mean_oracle'])}.")
c = r['check']
w(f"- **Сверка цепочки:** ответы {c['n_heads']} голов на {c['n']} задачах пилота OCREP-01 " + ('совпали' if c['answers_equal'] else 'НЕ СОВПАЛИ') + f"; наибольшее расхождение logp — {n(c['max_abs_dlogp'], 6)} (допуск {n(r['check_tol'], 3)}).")
w(f"- **Защита LR:** наибольшая доля повторов с одним классом — {n(r['lr_one_class']['max_share'], 4)}.")
w('')
w('## 2. Вердикты по PREREG (§5)')
for k, e in (('R1', R1), ('R2', R2), ('R3', R3)):
    t = e['tails']
    lo = e['leave_one_range_out']
    w(f"- **{k} — «{reading(k)}».** Δ {n(e['delta'], 4, True)}; ДИ BC {ci(e)}, процентильный {ci(e, key='ci_percentile')}, обратный {ci(e, key='ci_basic')}; "
      f"z₀ {n(e['z0'], 3, True)}, сдвиг «медиана повторов − точка» {n(e['boot_shift'], 4, True)}.")
    w(f"  - По каждому интервалу: BC — «{e['verdict_bc']}», процентильный — «{e['verdict_percentile']}», обратный — «{e['verdict_basic']}». "
      f"Повторов за границами BC: {e['n_out']['bc'][0]} и {e['n_out']['bc'][1]}; процентильного: {e['n_out']['percentile'][0]} и {e['n_out']['percentile'][1]}. "
      f"По другую сторону нуля: ниже — {e['n_below_0']}, выше — {e['n_above_0']} из {r['B']}. Половины повторов: «{t['verdict_halves'][0]}» и «{t['verdict_halves'][1]}»"
      + (' — граница по Монте-Карло неустойчива.' if t['unstable'] else '.'))
    if e['bc_note']:
        w(f"  - Метка: {e['bc_note']}.")
    ins = fa['bias'][k]['point_inside']
    if not all(ins.values()):
        w(f"  - Точка лежит вне интервалов: " + ', '.join(nm for key, nm in (('ci', 'BC'), ('ci_percentile', 'процентильного'), ('ci_basic', 'обратного')) if not ins[key])
          + f". Повторы смещены на {n(abs(fa['bias'][k]['shift_in_sd']), 1)} своих стандартных отклонений; интервалы — не независимые опоры.")
    w(f"  - **Строгая ветвь** (п. 4 решения совета 60 дословно): «{e['verdict_strict']}».")
    w(f"  - Без одного диапазона: знак среднего " + ('сохраняется' if lo['holds'] else 'НЕ сохраняется') + ' при исключении любого диапазона ('
      + '; '.join(f"без X = {g}: {n(v, 4, True)}" for g, v in lo['mean_without'].items()) + f"). Сред того же знака, что среднее, — {lo['n_same_sign']} из {lo['n']}.")
    if k == 'R2':
        nb = e['normal_bound']
        w(f"  - Нормальная граница: точка + 2,807·SE = {n(nb['upper'], 4, True)} (SE {n(nb['se'], 4)}) — " + ('ниже нуля.' if nb['holds'] else 'НЕ ниже нуля.'))
    if k == 'R1':
        rd, di, dd = e['reading'], D('D1: разность незнания'), D('D1: разность самообмана')
        w(f"  - Разложение D1: разность незнания {n(di['delta'], 4, True)} (BC {ci(di)}, процентильный {ci(di, key='ci_percentile')}, обратный {ci(di, key='ci_basic')}); "
          f"разность самообмана {n(dd['delta'], 4, True)} (BC {ci(dd)}, процентильный {ci(dd, key='ci_percentile')}, обратный {ci(dd, key='ci_basic')}). "
          f"Чтение по правилу PREREG §5: если «подтверждено» — «{rd['if_confirmed']}»; если «опровергнуто» — «{rd['if_refuted']}».")
    w(f"  - Мощность при эффекте, ужатом вдвое (по трём готовым сдвигам): {n(pw[k]['reading_power'])}.")
mt = R1['max_t']
w(f"- **R1, проверка после отбора (max-T):** наибольшее t — у {mt['best']} ({n(mt['t_max'], 2, True)}); порог {n(mt['crit'], 2)}; " + ('значимо' if mt['significant'] else 'не значимо') + f"; по половинам повторов p = {mt['halves'][0]['p']:.4f} и {mt['halves'][1]['p']:.4f}".replace('.', ',') + '. Положительное t значит, что оценщик толпы лучше одной головы.')
w(f"- **R4:** Q = {n(R4['Q'], 2)}, степеней свободы {R4['df']}; мощность при разбросе, ужатом вдвое, — {n(pw['R4']['reading_power'])}. Неоднородность D1 по средам (описательно): Q = {n(R4['descr_R1']['Q'], 2)}.")
w('- Ложное «подтверждено» по серии из четырёх правил — не выше 0,01; ложный вывод любого знака — не выше 0,0175 (семь сторон по 0,0025).')
w('')
w('## 3. Ожидания (PREREG §7)')
w('| № | ожидание | вероятность | исход |')
w('|---|---|---|---|')
txt = {'E1': 'R1 подтверждено', 'E2': 'R1 опровергнуто', 'E3': 'R2 подтверждено', 'E4': 'R3 подтверждено (CONF лучше)', 'E5': 'R3 опровергнуто (LR-AGREE лучше)',
       'E6': 'R4 подтверждено', 'E7': 'проверки метода опыта пройдены', 'E8': 'ONE-BEST — pythia-2.8b-deduped не меньше чем в 8 средах'}
for k in txt:
    w(f"| {k} | {txt[k]} | {n(fa['expectations_prereg'][k], 2)} | {'да' if fa['expectations_outcome'][k] else 'нет'} |")
w(f"- Брайер этих восьми ставок — {n(fa['brier_ocshift'], 3)}. Ожидания пересмотрены до прогона (PREREG §7, ERRORS № 165); по значениям черновика Брайер был бы {n(fa['brier_ocshift_draft'], 3)}.")
w('- Главный промах — E4: подтверждение R3 в сторону CONF я считал маловероятным (0,11), потому что на трёх прежних сдвигах в среднем лучше была LR-AGREE.')
w('')
w('## 4. Описательно (вес 0, без вердикта; интервалы уровня 0,005 на сторону)')
w('В скобках — интервал BC. Значок ° стоит там, где хотя бы один из трёх интервалов (BC, процентильный, обратный) не исключает ноль; без значка — все три по одну сторону нуля.')
w(f"- Описательных сравнений с интервалом — {fa['descr_count']}, по 0,005 на сторону, без поправки; общий ложный уровень серии — до {n(fa['descr_family_level_bonferroni'], 2)} (Бонферрони, оценка).")
w('- **ONE-BEST против каждого из восьми** (среднее по средам, ИОИ; минус — ONE-BEST лучше): ' + '; '.join(f"{e} {n(D(f'ONE-BEST − {e}')['delta'], 4, True)} {cz(D(f'ONE-BEST − {e}'))}" for e in EV) + '.')
w(f"- **Брайер выбранной заявки** (ИОИ не штрафует заниженную заявку): ONE-BEST {n(M['ONE-BEST']['brier'])}, лучший из восьми {n(M['MIN8']['brier'])}; разность {n(D('Брайер ONE-BEST − MIN8')['delta'], 4, True)} {cz(D('Брайер ONE-BEST − MIN8'))}.")
w(f"- **Точность выбора:** ONE-BEST {n(M['ONE-BEST']['T'])}; LR-AGREE {n(M['LR-AGREE']['T'])} (разность {n(D('T ONE-BEST − T LR-AGREE')['delta'], 4, True)} {cz(D('T ONE-BEST − T LR-AGREE'))}); CONF {n(M['CONF']['T'])} (разность {n(D('T ONE-BEST − T CONF')['delta'], 4, True)} {cz(D('T ONE-BEST − T CONF'))}).")
sw = fa['switch']
w('- **Где выбор отходит от ответа ONE-BEST** (среднее по средам: доля задач; точность выбранного там; точность ONE-BEST там): ' + '; '.join(f"{e} — {n(sw[e]['switch'])}; {n(sw[e]['T_selected_on_switch'])}; {n(sw[e]['T_one_best_on_switch'])}" for e in ('LR-AGREE', 'CONF', 'AGREE')) + '.')
sd = fa['selection_deception']
